import ReviewInsight from '../models/ReviewInsight.js';
import { demoProvider } from '../lib/ai/provider.js';
import { runGeneration } from '../lib/reviews/service.js';

// Pre-generates insights for 20 active professionals, spread evenly over the categories. The rest are generated
// the first time someone opens their profile. Generated by the real pipeline in demo mode from the seeded reviews.
export async function seedReviewInsights({ professionals }, count = 20) {
  await ReviewInsight.deleteMany({});
  const byCategory = new Map();
  for (const p of professionals.filter((x) => x.profileStatus === 'active')) {
    if (!byCategory.has(p.categorySlug)) byCategory.set(p.categorySlug, []);
    byCategory.get(p.categorySlug).push(p);
  }
  const picked = [];
  for (let round = 0; picked.length < count; round++) {
    let added = false;
    for (const list of byCategory.values()) if (list[round] && picked.length < count) { picked.push(list[round]); added = true; }
    if (!added) break;
  }
  for (const p of picked) await runGeneration(p._id, demoProvider);
  return picked;
}
